/**
 * The corrections ledger of the en.wiktionary second oracle for Latin (grammar design §8.4). Wiktionary's tables are the
 * output of another engine (Module:la-verb): where a table differs from this pack, a record states what the authority
 * says, with the A&G page, Bennett section or Lewis & Short entry read for it (never Wiktionary itself). A form an
 * authority prints as part of the classical paradigm is generated by the engine, never dropped here; what is dropped
 * is what the authorities print only as old, archaic or early forms, or do not print at all.
 */
import { startCorrection } from '../model.ts';
import type { CorpusCell, CorpusCorrection, CorpusFile, CorrectionDraft } from '../model.ts';
import type { WiktionaryPage } from '../sources/wiktionary-la.ts';

import { ag, bennett, lewisShort, scan } from './latin-urls.ts';

const fileOf = (page: WiktionaryPage): CorpusFile => ({
  file: page.title, language: 'la', infinitive: page.infinitive, gender: 'masculine', auxiliary: null, pattern: 'default', templatePlaceholders: 0,
  cells: page.cells,
});

/**
 * The footnote texts of a cell, read from the `[n]` marks of its `original`. The table puts a mark after the last of
 * the forms it concerns, so a note is read as concerning the cell's alternatives (every form but the first).
 */
function footnotes(page: WiktionaryPage, cell: CorpusCell): string[] {
  return [...cell.original.matchAll(/\[(\d+)\]/gu)].map(match => page.notes[match[1]!] ?? '');
}

const perfectSystem = (cell: CorpusCell): boolean =>
  ['perfect', 'pluperfect', 'future_perfect'].includes(cell.target.tense ?? '') && cell.target.mood !== 'participle';
const key = (cell: CorpusCell): string => `${cell.target.mood}.${cell.target.tense}${cell.voice ? `.${cell.voice}` : ''}${cell.subject ? `.${cell.subject}` : ''}`;

/** Drops the expected forms `unwanted` selects; records the reason only when something was dropped. */
function drop(draft: CorrectionDraft, unwanted: (form: string) => boolean, reason: string, source: string): void {
  const kept = draft.expected.filter(form => !unwanted(form));
  if (kept.length === draft.expected.length) return;
  if (kept.length === 0) {
    draft.markUnavailable(reason, source);
    return;
  }
  draft.expected = kept;
  draft.note(reason, source);
}

/**
 * The contractions the authorities print, as a fixed table of substitutions on the full form, each with the examples it
 * is read from (A&G §181 p. 91; Bennett §116.1). It is the ledger's own reading of the grammar, not the engine's rule.
 */
const contractions: readonly (readonly [pattern: RegExp, replacement: string, examples: string])[] = [
  [/([āēō])vi(?=ss)/u, '$1', 'amāvisse → amāsse, amāvissem → amāssem, nōvisse → nōsse (A&G §181.a)'],
  [/([āēō])vi(?=st)/u, '$1', 'flēvistis → flēstis (A&G §181.a); amāvistī → amāstī, nōvistī → nōstī (Bennett §116.1)'],
  [/([āēō])ve(?=r)/u, '$1', 'amāverim → amārim, cōnsuēverat → cōnsuērat, commōverat → commōrat (A&G §181.a)'],
  [/([āēō])vē(?=r)/u, '$1', 'amāvērunt → amārunt, dēlēvērunt → dēlērunt (Bennett §116.1)'],
  [/īvi(?=s)/u, 'ī', 'audīvisse → audīsse, audīvistī → audīstī (A&G §181.b)'],
  [/īv(?=[eēiī])/u, 'i', 'audīveram → audieram, abīvit → abiit, abīvērunt → abiērunt (A&G §181.b)'],
];

/** The forms the table above derives from a cell's full form. */
const contracted = (full: string): string[] => contractions.map(([pattern, replacement]) => full.replace(pattern, replacement)).filter(form => form !== full);

const auxiliaries: Readonly<Record<string, readonly string[]>> = {
  'indicative.perfect': ['sum', 'es', 'est', 'sumus', 'estis', 'sunt'],
  'indicative.pluperfect': ['eram', 'erās', 'erat', 'erāmus', 'erātis', 'erant'],
  'indicative.future_perfect': ['erō', 'eris', 'erit', 'erimus', 'eritis', 'erunt'],
  'subjunctive.perfect': ['sim', 'sīs', 'sit', 'sīmus', 'sītis', 'sint'],
  'subjunctive.pluperfect': ['essem', 'essēs', 'esset', 'essēmus', 'essētis', 'essent'],
};
const slotIndex = (subject: string): number => ['1sg', '2sg', '3sg', '1pl', '2pl', '3pl'].indexOf(subject.replace(/\.m$/u, ''));

/** Intransitive verbs whose passive is impersonal (A&G §207 table: pūgnātur, pūgnātum est, pūgnātum esse; §208.d). */
const impersonalPassive = new Set(['sto', 'sedeo', 'cado', 'venio', 'redeo', 'curro']);
const perfectOnly: Readonly<Record<string, string>> = { odi: 'ōdī', memini: 'meminī' };
const shiftedTense: Readonly<Record<string, string>> = { present: 'perfect', imperfect: 'pluperfect', future: 'future_perfect' };

export function wiktionaryLatinCorrection(page: WiktionaryPage, cell: CorpusCell, index: number): CorpusCorrection | null {
  if (cell.scope === 'unmodelled') return null;
  const draft = startCorrection(fileOf(page), cell, index);
  const notes = footnotes(page, cell);
  const first = cell.expected[0];
  const noted = (pattern: RegExp) => (form: string): boolean => form !== first && notes.some(note => pattern.test(note));
  const { mood, tense } = cell.target;

  // (1) Footnoted forms the table itself calls poetic, archaic, Old or Late Latin.
  drop(draft, form => noted(/-ier/u)(form) && form.endsWith('ier'),
    'The present passive infinitive in -ier is among the ancient forms "found chiefly in poetry" (A&G §183.4: vocārier, agier; Bennett §116.4.a); the classical form is generated.',
    scan(91));
  const full = cell.expected[0] ?? '';
  drop(draft, form => noted(/syncopated/u)(form) && !contracted(full).includes(form),
    'A&G §181 contracts -āvi-, -ēvi-, -ōvi- only before s and r (never in the 1st singular, very rarely in the 3rd) and lets -īvī perfects lose v, contracting ii only before st and ss; this rare poetic form (the table\'s footnote) is outside that rule.',
    scan(91));
  drop(draft, noted(/Old Latin or in poetry/u),
    'An old form of the present subjunctive or the future of sum (A&G §170 Note: siem, siēs, siet, sient; fuam, fuās, fuat, fuant), which its compounds share (§198); the classical prōsim, absim are generated.',
    scan(83));
  if (page.title === 'scio') {
    drop(draft, form => noted(/pre-classical/u)(form) && /^scīb/u.test(form),
      'The imperfect -ībam and future -ībō of the fourth conjugation are ancient forms "found chiefly in poetry" (A&G §183.1; Bennett §116.4.b); the classical sciēbam, sciam are generated.',
      scan(91));
  }
  if (page.title === 'dico') {
    drop(draft, form => noted(/pre-classical/u)(form) && /^dīcēb/u.test(form),
      'The future of the third conjugation is in -am, -ēs (A&G §186, p. 98: tegam, tegēs, teget); the pre-classical -ēbō future the table adds is printed by no authority read for this pack.',
      scan(98));
    drop(draft, form => ['dīxtī', 'dīxe'].includes(form),
      'dīxtī for dīxistī and the like "belong to archaic and colloquial usage" (A&G §181 Note 2); the full forms are generated.', scan(91));
  }
  if (page.title === 'facio') {
    drop(draft, noted(/Late Latin/u), 'fāre is Late Latin (the table\'s own footnote); A&G §204 (p. 115) gives faciō, facere, fēcī, factum.', scan(115));
    if (key(cell) === 'imperative.future.passive.2pl.m') {
      draft.markUnavailable('The passive of faciō is fīō, whose imperative A&G p. 115 prints only as [fī, fīte, fītō, ——], "rarely found, and then only in early writers": no fītōte.', scan(115));
    }
  }

  // (2) Alternatives the authorities print as old or early forms, or do not print.
  if (page.title === 'scio' && key(cell) === 'imperative.present.active.2sg.m') {
    drop(draft, form => form === 'scī', '"For the imperative of sciō, the future form scītō is always used in the singular" (A&G §182.a): no scī.', scan(91));
  }
  if (['duco', 'dico', 'facio'].includes(page.title) && mood === 'imperative') {
    drop(draft, form => ['dūce', 'dīce', 'face'].includes(form),
      'The imperative forms dīce, dūce, face "occur in early Latin" (A&G §182 Note); the classical imperative is dīc, dūc, fac (A&G §182).', scan(91));
  }
  if (page.title === 'do') {
    drop(draft, form => form === 'danunt', 'Bennett §127 prints the present dō, dās, dat; damus, datis, dant; danunt is an old form no authority read here prints.', bennett(127));
    drop(draft, form => /^du[āīi]/u.test(form),
      'duim, duint "are archaic and poetic Present Subjunctive forms ... from du-, a collateral root" (Bennett §127.2; A&G §183.2: retained in religious formulas); the classical dem, dēs are generated.',
      bennett(127));
    if (cell.voice === 'passive' && cell.subject === '1sg.m' && tense === 'present') {
      draft.markUnavailable('A&G p. 113 prints a dash for the first singular present passive of dō, indicative and subjunctive: dor and der are not attested.', scan(113));
    }
  }
  if (perfectSystem(cell) || (mood === 'infinitive' && tense === 'perfect')) {
    if (page.title === 'curro') drop(draft, form => form.startsWith('curr'), 'A&G §211 gives currō, cucurrī, curs-: the perfect is reduplicated; currī is not printed.', ag('classified-lists-verbs-3rd-conjugation'));
    if (page.title === 'teneo') drop(draft, form => form.startsWith('tetin'), 'A&G §210 gives teneō, tenuī, tent-; the old reduplicated tetinī is not printed.', ag('classified-lists-verbs-1st-and-2nd-conjugations'));
    if (page.title === 'pono') drop(draft, form => form.startsWith('posī'), 'A&G §211 gives pōnō, posuī, posit-; the old perfect posīvī is not printed.', ag('classified-lists-verbs-3rd-conjugation'));
    drop(draft, form => /iis/u.test(form),
      'ii before s contracts to ī in the perfect of eō and of -īvī perfects that lose v (A&G §203.c: īsse; §181.b: audīstī, audīsse); the uncontracted form is not printed.',
      scan(91));
  }
  if (page.title === 'morior') {
    draft.change('The table marks the i as of either quantity (ī̆); morior inflects like capiō (Bennett §109.2.c): moritur, morimur.', bennett(109), form => form.replace(/ī̆/gu, 'i'));
    drop(draft, form => /^morī[rt]/u.test(form) || /^morīr/u.test(form),
      'morior is a third-conjugation verb in -iō (Bennett §109.2.c): moreris, morerer, morī; Lewis & Short lists morīmur, morīrī as "old forms acc. to the fourth conj." (Ennius, Plautus, Ovid), which are not generated.',
      lewisShort('morior'));
    if (mood === 'supine') draft.markUnavailable('Lewis & Short gives morior, mortuus, moritūrus: no supine (the participle mortuus is not a supine stem).', lewisShort('morior'));
  }
  if (page.title === 'nascor') {
    drop(draft, form => form.startsWith('gnāt'), 'gnātus is the ante-classical and poetic spelling (Lewis & Short s.v. nascor); the classical nātus is generated.', lewisShort('nascor'));
  }
  if (page.title === 'edo') {
    if (cell.voice === 'passive' || mood === 'participle' || mood === 'supine' || (mood === 'infinitive' && tense !== 'present' && tense !== 'perfect')) {
      drop(draft, form => /^ēss/u.test(form) && form !== 'ēssētur',
        'A&G §201 gives the passive athematic forms only in the third singular (ēstur, ēssētur), and ēssūrus, ēssum as old forms; the other ēss- forms are not printed.',
        ag('irregular-verbs-fer%C5%8D-and-ed%C5%8D'));
    }
    if (cell.voice === 'passive' && mood === 'imperative') {
      drop(draft, form => form.startsWith('ēs'), 'A&G §201 prints no athematic passive imperative of edō (only ēstur, ēssētur in the third singular).', ag('irregular-verbs-fer%C5%8D-and-ed%C5%8D'));
    }
    if (mood === 'subjunctive' && tense === 'present') drop(draft, form => form === 'ēst', 'A&G §201 prints the present subjunctive edam (edim), edat (edit); ēst is indicative only.', ag('irregular-verbs-fer%C5%8D-and-ed%C5%8D'));
  }
  if (['prosum', 'absum'].includes(page.title) && mood === 'subjunctive' && tense === 'imperfect') {
    drop(draft, form => /forē(?:mus|tis)$/u.test(form), 'A&G §170.a prints forem, forēs, foret, forent beside essem: no forēmus, forētis (Bennett §100 likewise).', scan(83));
  }
  if (page.title === 'pono') {
    drop(draft, form => /(?:^|\s)post(?:ū|um|us)/u.test(form) || /^post[uū]/u.test(form), 'A&G §211 gives pōnō, posuī, posit-: the supine stem is posit-; the syncopated postus is not printed.', ag('classified-lists-verbs-3rd-conjugation'));
  }
  if (page.title === 'queo' && (cell.voice === 'passive' || ['imperative', 'gerund', 'supine'].includes(mood ?? '') || (mood === 'participle' && tense !== 'present') || (mood === 'infinitive' && tense === 'future'))) {
    draft.markUnavailable('queō: "The Imperative, Gerund, and Supine are wanting", and its few passive forms are "used with passive infinitives" only (A&G §206.d), a construction; no supine stem, so no participle or infinitive built on it.', ag('defective-verbs'));
  }
  if (page.title === 'memini' && (key(cell) === 'imperative.future.active.3sg.m' || (mood === 'participle' && tense === 'present'))) {
    draft.markUnavailable('meminī has only the imperative mementō, mementōte (Bennett §133); "a present participle meminēns is early and late" (A&G §205.b Note 1).', bennett(133));
  }
  if (page.title === 'odi' && (mood === 'supine' || (mood === 'infinitive' && tense === 'perfect' && cell.target.agreement !== null))) {
    draft.markUnavailable('Bennett §133 gives ōdī the infinitives ōdisse, ōsūrus esse and the participles ōsus, ōsūrus: no supine and no ōsum esse.', bennett(133));
  }
  if (['prosum', 'absum'].includes(page.title) && key(cell) === 'infinitive.future.active') {
    const participle = page.title === 'prosum' ? 'prōfutūrum' : 'āfutūrum';
    draft.expected = [`${participle} esse`, ...draft.expected];
    draft.correctedTarget = { ...cell.target, agreement: { gender: 'masculine', number: 'singular', case: 'accusative' } };
    draft.note('The future infinitive of a compound of sum is the participle with esse, beside fore (A&G p. 108: prōfutūrus esse; p. 83: futūrus esse or fore); the table gives only the fore form.', scan(108));
  }
  if (['prosum', 'absum'].includes(page.title) && key(cell) === 'indicative.future.active.2sg.m') {
    drop(draft, form => form.endsWith('re'), 'The future of sum is erō, eris (A&G p. 82); -re is an ending of the passive (A&G §163), not of sum or its compounds.', scan(82));
  }

  // (3) The semi-deponent audeō: its perfect system is ausus sum (A&G §192; 31 cells).
  if (page.title === 'audeo') {
    const chain = auxiliaries[`${mood}.${tense}`];
    if (chain && cell.subject) {
      const slot = slotIndex(cell.subject);
      draft.expected = [`${slot < 3 ? 'ausus' : 'ausī'} ${chain[slot]!}`];
      draft.note('audeō is semi-deponent: its perfect system is passive in form, ausus sum (A&G §192; Bennett §114); the active ausī is not printed.', ag('deponent-verbs'));
    }
    if (mood === 'infinitive' && tense === 'perfect' && cell.voice === 'active') {
      draft.expected = ['ausum esse'];
      draft.correctedTarget = { ...cell.target, agreement: { gender: 'masculine', number: 'singular', case: 'accusative' } };
      draft.note('audeō is semi-deponent: its perfect infinitive is ausus esse (A&G §192), in the accusative ausum esse; ausisse is not printed.', ag('deponent-verbs'));
    }
  }

  // (4) Classes: verbs perfect in form, impersonal passives, impersonal verbs, missing supines.
  if (perfectOnly[page.title] && cell.target.tense && shiftedTense[cell.target.tense] && (mood === 'indicative' || mood === 'subjunctive')) {
    const shifted = mood === 'subjunctive' ? (tense === 'present' ? 'perfect' : 'pluperfect') : shiftedTense[cell.target.tense]!;
    draft.correctedTarget = { ...cell.target, tense: shifted as never };
    draft.note(`${perfectOnly[page.title]} is perfect in form and present in sense (Bennett §133.2; A&G §205): the table's present, imperfect and future are its perfect, pluperfect and future perfect.`, bennett(133));
  }
  if (perfectOnly[page.title] && mood === 'infinitive' && tense === 'present' && cell.voice === 'active') {
    draft.correctedTarget = { ...cell.target, tense: 'perfect' };
    draft.note(`${perfectOnly[page.title]} is perfect in form (Bennett §133): its infinitive is the perfect infinitive.`, bennett(133));
  }
  if (impersonalPassive.has(page.title)) {
    if (cell.voice === 'passive' && (mood === 'indicative' || mood === 'subjunctive') && cell.subject !== '3sg.m' && draft.expected.length) {
      draft.markUnavailable('The passive of an intransitive verb is impersonal, used only in the third person singular (A&G §207: "the passive of many intransitive verbs is used in the same way"; curritur).', ag('impersonal-verbs'));
    }
    if (mood === 'participle' && tense === 'perfect') {
      draft.markUnavailable('An intransitive verb has no personal perfect participle: its passive is impersonal, in the third singular with the neuter (A&G §207 table: pūgnātum est; §208.d).', ag('impersonal-verbs'));
    }
    if ((mood === 'infinitive' && tense === 'perfect' && cell.voice === 'passive') || (mood === 'participle' && tense === 'gerundive')) {
      draft.correctedTarget = { ...cell.target, agreement: { gender: 'neuter', number: 'singular', case: mood === 'infinitive' ? 'accusative' : 'nominative' } };
      draft.expected = draft.expected.map(form => form.replace(/us$/u, 'um'));
      draft.note('The impersonal passive stands in the neuter singular (A&G §207 table: pūgnātum esse; the gerundive eundum, p. 114): the table prints the neuter form.', ag('impersonal-verbs'));
    }
    if (mood === 'imperative' && cell.voice === 'passive' && draft.expected.length) {
      draft.markUnavailable('The impersonal passive is used in the third person singular of the finite tenses (A&G §207 table, §208.d); no imperative is printed.', ag('impersonal-verbs'));
    }
  }
  if (['oportet', 'pluit'].includes(page.title) && (mood === 'imperative' || (mood === 'participle' && tense === 'present'))) {
    draft.markUnavailable('Impersonal verbs "appear only in the 3rd person singular, the infinitive, and the gerund" (A&G §207): no imperative and no present participle.', ag('impersonal-verbs'));
  }
  if (['gaudeo', 'audeo'].includes(page.title) && mood === 'supine') {
    draft.markUnavailable('A&G §192 gives audeō, ausus sum and gaudeō, gāvīsus sum: a semi-deponent has the participle, no supine (Bennett §114).', ag('deponent-verbs'));
  }
  if (page.title === 'gradior' && mood === 'participle' && tense === 'gerundive') {
    draft.markUnavailable('An intransitive deponent has the gerundive only impersonally (A&G §190.d; gradior is "v. dep. n.", Lewis & Short): no personal gradiendus.', ag('deponent-verbs'));
  }
  if (page.title === 'gaudeo' && mood === 'participle' && tense === 'gerundive') {
    draft.markUnavailable('gaudeō is taken as intransitive, whose gerundive is only impersonal (A&G §190.d): no personal gaudendus (Lewis & Short gives the verb as "v. n. and a.": a recorded choice).', ag('deponent-verbs'));
  }
  if (page.title === 'coepi' && (mood === 'supine' || (mood === 'infinitive' && cell.voice === 'passive'))) {
    draft.markUnavailable('coepī has the passive coeptus est only with a passive infinitive (Bennett §133.1; A&G §205.a), a construction; no supine and no passive infinitive of its own.', bennett(133));
  }
  return draft.finish();
}
